"use client";

import { useState, type ReactNode } from "react";
import { motion, useReducedMotion } from "framer-motion";

export function HoverBorderGradientButton({
  children,
  onClick,
}: {
  children: ReactNode;
  onClick?: () => void;
}) {
  const [active, setActive] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  return (
    <button
      type="button"
      onClick={onClick}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onFocus={() => setActive(true)}
      onBlur={() => setActive(false)}
      className="relative inline-flex items-center justify-center overflow-hidden rounded-full p-[1.5px] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-600"
    >
      <motion.span
        aria-hidden
        className="absolute inset-[-60%]"
        style={{
          background:
            "conic-gradient(from 0deg, transparent 0%, #10b981 12%, #f59e0b 20%, transparent 38%)",
        }}
        animate={{ opacity: active ? 1 : 0, rotate: shouldReduceMotion ? 0 : 360 }}
        transition={{
          opacity: { duration: 0.25, ease: "easeOut" },
          rotate: { duration: active ? 2 : 5.5, repeat: Infinity, ease: "linear" },
        }}
      />
      <span className="relative z-10 inline-flex items-center justify-center rounded-full bg-white px-5 py-2.5 text-sm font-medium text-slate-900 transition-colors duration-300 dark:bg-black dark:text-white">
        {children}
      </span>
    </button>
  );
}
